![medium](https://www.gstatic.com/codereviewagent/medium-priority.svg)

If the spawned child process emits an 'error' event, the finish callback is invoked with exit code 127. However, the 'close' event may still be emitted afterwards, causing finish to be called a second time and overwriting the exit code. Use a guard flag to ensure the finish callback is executed exactly once.

```typescript
function startBackgroundProcess(command: string[], appendLine: (line: string) => void, finish: (code: number) => void): void {
  let finished = false;
  const safeFinish = (code: number) => {
    if (finished) {
      return;
    }
    finished = true;
    finish(code);
  };

  const child = spawn(command[0], command.slice(1), {
    cwd: process.cwd(),
    env: { ...process.env, AIDEVOPS_NON_INTERACTIVE: "true", CLICOLOR_FORCE: "1", FORCE_COLOR: "1", TERM: process.env.TERM ?? "xterm-256color" },
    stdio: ["ignore", "pipe", "pipe"]
  });
  if (child.stdout !== null) {
    readline.createInterface({ input: child.stdout, terminal: false }).on("line", appendLine);
  }
  if (child.stderr !== null) {
    readline.createInterface({ input: child.stderr, terminal: false }).on("line", appendLine);
  }
  child.on("error", (error) => {
    appendLine(error.message);
    safeFinish(127);
  });
  child.on("close", (code) => safeFinish(code ?? 1));
}
