Deduplicate the evidence references to avoid redundant items (such as multiple identical repository references) from being displayed in the UI.

```typescript
function evidenceRefs(events: GuiPulseWorkerActivityEvent[]): string[] {
  const refs = events.flatMap(
    (event) =>
      [event.repo_ref, event.issue_ref, event.pull_request_ref, event.worker_session_ref, event.command_job_ref].filter(
        Boolean,
      ) as string[],
  );
  return Array.from(new Set(refs)).slice(0, 8);
}
